[CmdletBinding()]
param([string]$InventoryPath='project-state/master-inventory.json',[string]$DecisionPath='project-state/discovery/go2011-bond-cluster-research-2026-09-11.json')
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$i=Get-Content $InventoryPath -Raw|ConvertFrom-Json;$a=Get-Content $DecisionPath -Raw|ConvertFrom-Json;$x=@{};foreach($c in $i.candidates){$x[[string]$c.id]=$c};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
function Set-Go2011($row,[string]$status){$id=[string]$row.id;if(-not $seen.Add($id)){throw "duplicate $id"};$c=$x[$id];if(-not$c){throw "missing $id"};if($c.status-ne'pending review'){throw "unexpected $id=$($c.status)"};$url=[string]$row.authoritative_url;$c.direct_file_url=$url;if(@($c.referring_urls)-notcontains$url){$c.referring_urls=@($c.referring_urls)+@($url)};$e=$row.PSObject.Properties['evidence'];$r=$row.PSObject.Properties['reason'];$why=if($r -and $r.Value){[string]$r.Value}elseif($e){[string]$e.Value}else{'Reviewed in the dated research artifact.'};if($status-eq'approved for addition'){$c.title=[string]$row.title;$c.description=[string]$row.description;$c.description_word_count=[int]$row.description_word_count;$c.proposed_canonical_page=[string]$row.proposed_canonical_page;$c.size_bytes=[int64]$row.size_bytes;$c.checksum_sha256=[string]$row.checksum_sha256;$c.implementation_locations=@([string]$row.proposed_canonical_page);$c.validation_status='passed: authoritative City PDF reviewed and HTTP 200 verified; awaiting authorized editorial placement';$c.exclusion_reason=$null}elseif($status-eq'duplicate'){$canonical=$x[[string]$row.canonical_id];if(-not$canonical){throw "missing canonical $($row.canonical_id)"};$curl=if($canonical.direct_file_url){[string]$canonical.direct_file_url}else{[string]$canonical.source_url};$c.cited_successors=@($c.cited_successors)+@($curl)|Select-Object -Unique;$c.validation_status='terminal research decision: duplicate by exact, normalized-text, or contained-content comparison';$c.exclusion_reason="Duplicate or contained component of canonical inventory record $($row.canonical_id). $why"}elseif($status-eq'requires human review'){$c.validation_status='requires human review: version or independent-record value remains unresolved';$c.exclusion_reason=$null}else{$c.validation_status='terminal research decision: excluded';$c.exclusion_reason=$why};$n="$($a.batch_id) integration: $why";if(@($c.processing_notes)-notcontains$n){$c.processing_notes=@($c.processing_notes)+@($n)};$c.status=$status;$c.updated_at=(Get-Date).ToUniversalTime().ToString('o')}
foreach($r in @($a.approved_for_addition)){Set-Go2011 $r 'approved for addition'};foreach($r in @($a.duplicate)){Set-Go2011 $r 'duplicate'};foreach($r in @($a.requires_human_review)){Set-Go2011 $r 'requires human review'};foreach($r in @($a.excluded)){Set-Go2011 $r 'excluded'};if($seen.Count-ne[int]$a.counts.reviewed){throw "unexpected count $($seen.Count)"};$counts=[ordered]@{};foreach($s in $i.allowed_statuses){$counts[$s]=@($i.candidates|Where-Object{[string]$_.status-eq$s}).Count};$i.counts=[pscustomobject]$counts;$next=@($i.candidates|Where-Object{$_.status -in @('pending review','approved for addition','downloaded','parsed','description drafted','placement assigned') -or ($_.status-eq'implemented' -and $_.validation_status-ne'passed')}|Sort-Object id|Select-Object -First 1);$i.next_pending_id=if($next.Count){$next[0].id}else{$null};$i.generated_at=(Get-Date).ToUniversalTime().ToString('o');$full=[IO.Path]::GetFullPath($InventoryPath);$tmp="$full.tmp-$PID";try{[IO.File]::WriteAllText($tmp,($i|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $tmp -Destination $full -Force}finally{if(Test-Path $tmp){Remove-Item $tmp -Force}};[pscustomobject]@{integrated=$seen.Count;counts=$i.counts;next_pending_id=$i.next_pending_id}|ConvertTo-Json -Depth 5
